pm.test("HTTP 200 - Listagem realizada com sucesso", function () {
    pm.response.to.have.status(200);
});

pm.test("Resposta no formato JSON", function () {
    pm.response.to.be.json;
});

pm.test("Resposta contém uma lista de eventos", function () {
    const eventos = pm.response.json();

    pm.expect(eventos).to.be.an("array");
});

pm.test("Eventos possuem os campos obrigatórios", function () {
    const eventos = pm.response.json();

    pm.expect(eventos.length).to.be.above(0);

    eventos.forEach(function (evento) {
        pm.expect(evento).to.have.property("id_evento");
        pm.expect(evento).to.have.property("nome");
        pm.expect(evento).to.have.property("data");
        pm.expect(evento).to.have.property("local");
        pm.expect(evento).to.have.property("vagas_disponiveis");
        pm.expect(evento).to.have.property("preco_ingresso");

        pm.expect(evento.vagas_disponiveis).to.be.at.least(0);
    });
});

pm.test("HTTP 201 - Ingresso criado com sucesso", function () {
    pm.response.to.have.status(201);
});

pm.test("Ingresso possui os campos obrigatórios", function () {
    const ingresso = pm.response.json();

    pm.expect(ingresso).to.have.property("id_ingresso");
    pm.expect(ingresso).to.have.property("evento_nome");
    pm.expect(ingresso).to.have.property("comprador_nome");
    pm.expect(ingresso).to.have.property("qrcode_hash");
    pm.expect(ingresso).to.have.property("status");
    pm.expect(ingresso).to.have.property("data_emissao");
});

pm.test("Ingresso está com status EMITIDO", function () {
    const ingresso = pm.response.json();

    pm.expect(ingresso.status).to.eql("EMITIDO");
});

pm.test("Hash SHA-256 possui 64 caracteres hexadecimais", function () {
    const ingresso = pm.response.json();

    pm.expect(ingresso.qrcode_hash).to.match(/^[a-fA-F0-9]{64}$/);
});

// Armazena os identificadores somente quando a emissão é bem-sucedida.
if (pm.response.code === 201) {
    const ingresso = pm.response.json();

    pm.collectionVariables.set("id_ingresso", ingresso.id_ingresso);
    pm.collectionVariables.set("qrcode_hash", ingresso.qrcode_hash);
}

pm.test("HTTP 200 - Check-in realizado com sucesso", function () {
    pm.response.to.have.status(200);
});

pm.test("Acesso ao evento foi liberado", function () {
    const resposta = pm.response.json();

    pm.expect(resposta.status_acesso).to.eql("LIBERADO");
});

pm.test("Resposta possui os campos obrigatórios", function () {
    const resposta = pm.response.json();

    pm.expect(resposta).to.have.property("status_acesso");
    pm.expect(resposta).to.have.property("comprador_nome");
    pm.expect(resposta).to.have.property("evento_nome");
    pm.expect(resposta).to.have.property("data_hora_checkin");
});

pm.test("Horário de check-in é válido", function () {
    const resposta = pm.response.json();

    pm.expect(
        Number.isNaN(Date.parse(resposta.data_hora_checkin))
    ).to.eql(false);
});

pm.test("HTTP 409 - Check-in duplicado bloqueado", function () {
    pm.response.to.have.status(409);
});

pm.test("Código de erro INGRESSO_JA_UTILIZADO", function () {
    const erro = pm.response.json();

    pm.expect(erro.codigo_erro).to.eql("INGRESSO_JA_UTILIZADO");
});

pm.test("Erro possui mensagem e timestamp", function () {
    const erro = pm.response.json();

    pm.expect(erro).to.have.property("mensagem");
    pm.expect(erro).to.have.property("timestamp");
});

pm.test("HTTP 200 - Ingresso consultado com sucesso", function () {
    pm.response.to.have.status(200);
});

pm.test("Ingresso possui os campos obrigatórios", function () {
    const ingresso = pm.response.json();

    pm.expect(ingresso).to.have.property("id_ingresso");
    pm.expect(ingresso).to.have.property("evento_nome");
    pm.expect(ingresso).to.have.property("comprador_nome");
    pm.expect(ingresso).to.have.property("qrcode_hash");
    pm.expect(ingresso).to.have.property("status");
    pm.expect(ingresso).to.have.property("data_emissao");
});

pm.test("Identificador corresponde ao ingresso emitido", function () {
    const ingresso = pm.response.json();

    pm.expect(ingresso.id_ingresso).to.eql(
        pm.collectionVariables.get("id_ingresso")
    );
});

pm.test("Ingresso apresenta status UTILIZADO", function () {
    const ingresso = pm.response.json();

    pm.expect(ingresso.status).to.eql("UTILIZADO");
});

pm.test("HTTP 404 - Ingresso não encontrado", function () {
    pm.response.to.have.status(404);
});

pm.test("Código de erro INGRESSO_NAO_ENCONTRADO", function () {
    const erro = pm.response.json();

    pm.expect(erro.codigo_erro).to.eql("INGRESSO_NAO_ENCONTRADO");
});

pm.test("Erro possui mensagem e timestamp", function () {
    const erro = pm.response.json();

    pm.expect(erro).to.have.property("mensagem");
    pm.expect(erro).to.have.property("timestamp");
});
